/**
 * Milestone domain rules that are not tied to storage: the state error, the
 * name-uniqueness key, the overdue predicate and the listing order.
 */
import type { IsoTimestamp } from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export type MilestoneStateReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

const MESSAGES: Readonly<Record<MilestoneStateReason, string>> = {
  closed: "is closed",
  already_open: "is already open",
  too_many_open: "cannot be opened: the project has too many open milestones",
  name_taken: "uses a name already taken in this project",
};

/** A milestone is in the wrong state for the requested operation. */
export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly reason: MilestoneStateReason,
    readonly milestoneId: string | null = null,
  ) {
    super(`Milestone ${milestoneId ?? ""} ${MESSAGES[reason]}`.replace(/\s+/g, " "));
    this.name = "MilestoneStateError";
  }
}

/** Names compare without regard to letter case or surrounding spaces. */
export function milestoneNameKey(name: string): string {
  return name.trim().toLowerCase();
}

export function isMilestoneOpen(milestone: Milestone): boolean {
  return milestone.closedAt === null;
}

/** Open, dated strictly in the past, with open issues remaining. */
export function isMilestoneOverdue(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: Date = new Date(),
): boolean {
  if (!isMilestoneOpen(milestone)) return false;
  if (milestone.targetDate === null) return false;
  if (progress.open === 0) return false;
  return new Date(milestone.targetDate).getTime() < now.getTime();
}

function compareDates(a: IsoTimestamp | null, b: IsoTimestamp | null): number {
  if (a === b) return 0;
  if (a === null) return 1;
  if (b === null) return -1;
  return new Date(a).getTime() - new Date(b).getTime();
}

/**
 * Open before closed; then target date ascending with undated last; then
 * creation, oldest first.
 */
export function compareMilestones(a: Milestone, b: Milestone): number {
  const openA = isMilestoneOpen(a) ? 0 : 1;
  const openB = isMilestoneOpen(b) ? 0 : 1;
  if (openA !== openB) return openA - openB;

  const byDate = compareDates(a.targetDate, b.targetDate);
  if (byDate !== 0) return byDate;

  const byCreated = compareDates(a.createdAt, b.createdAt);
  if (byCreated !== 0) return byCreated;
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}
