/**
 * Milestone rows and the per-milestone issue progress counts. Every method takes `orgId` first.
 */
import { and, asc, count, eq, inArray, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { milestoneNameKey } from "@/lib/milestones";
import { getDb, issues, milestones } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { toMilestone } from "./_mappers";
import type {
  IsoTimestamp,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

const EMPTY_PROGRESS: MilestoneProgress = { total: 0, open: 0, closed: 0 };

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/** Every milestone of a project, open and closed, in insertion order. */
export async function listMilestonesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .orderBy(asc(sql`rowid`))
    .all();
  return rows.map(toMilestone);
}

export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/** The milestone of `projectId` whose name collides with `name`, if any. */
export async function findMilestoneByName(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        eq(milestones.nameKey, milestoneNameKey(name)),
      ),
    )
    .get();
  return row ? toMilestone(row) : null;
}

export async function insertMilestone(input: {
  orgId: OrgId;
  projectId: ProjectId;
  name: string;
  targetDate: IsoTimestamp | null;
}): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());
  const name = input.name.trim();
  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name,
      nameKey: milestoneNameKey(name),
      targetDate:
        input.targetDate === null ? null : toIsoTimestamp(input.targetDate),
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toMilestone(row);
}

export async function updateMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  patch: {
    name?: string;
    targetDate?: IsoTimestamp | null;
    closedAt?: IsoTimestamp | null;
  },
): Promise<Milestone> {
  const name = patch.name?.trim();
  const row = getDb()
    .update(milestones)
    .set({
      ...(name === undefined ? {} : { name, nameKey: milestoneNameKey(name) }),
      ...(patch.targetDate === undefined
        ? {}
        : {
            targetDate:
              patch.targetDate === null
                ? null
                : toIsoTimestamp(patch.targetDate),
          }),
