/** Total / open / closed over each milestone's live issues. */
export async function getMilestoneProgress(
  orgId: OrgId,
  milestoneIds: readonly MilestoneId[],
): Promise<Readonly<Record<string, MilestoneProgress>>> {
  const out: Record<string, MilestoneProgress> = {};
  for (const id of milestoneIds) out[id] = EMPTY_PROGRESS;
  if (milestoneIds.length === 0) return out;

  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      status: issues.status,
      value: count(),
    })
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.milestoneId, [...milestoneIds]),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .groupBy(issues.milestoneId, issues.status)
    .all();

  for (const row of rows) {
    if (row.milestoneId === null) continue;
    const current = out[row.milestoneId] ?? EMPTY_PROGRESS;
    const closed = CLOSED_ISSUE_STATUSES.includes(row.status);
    out[row.milestoneId] = {
      total: current.total + row.value,
      open: current.open + (closed ? 0 : row.value),
      closed: current.closed + (closed ? row.value : 0),
    };
  }

  return out;
}
