import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
import { registerEventHandlers } from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import * as ms from "@/server/services/milestone-service";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { MilestoneStateError } from "@/lib/milestones";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;
let t: Tenant;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); t = await createTenant("ms"); registerEventHandlers(); });
afterAll(() => cleanup());

describe("milestones smoke", () => {
  it("works end to end", async () => {
    const a = t.actors.admin;
    const m1 = await ms.createMilestone(a, { orgId: t.org.id, projectId: t.project.id, name: " Beta ", targetDate: "2020-01-01T00:00:00.000Z" });
    await expect(ms.createMilestone(a, { orgId: t.org.id, projectId: t.project.id, name: "beta", targetDate: null })).rejects.toBeInstanceOf(MilestoneStateError);
    const m2 = await ms.createMilestone(a, { orgId: t.org.id, projectId: t.project.id, name: "Gamma", targetDate: null });
    const i1 = await issueService.createIssue(a, { ...issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.member }), milestoneId: m1.id });
    const i2 = await issueService.createIssue(a, issueInput(t.org.id, t.project.id));
    await issueService.setIssueMilestone(a, { orgId: t.org.id, issueId: i2.id, milestoneId: m1.id });
    let list = await ms.listMilestones(a, t.org.id, t.project.id);
    expect(list.map((x) => x.milestone.name)).toEqual(["Beta", "Gamma"]);
    expect(list[0]?.progress).toEqual({ total: 2, open: 2, closed: 0 });
    expect(list[0]?.overdue).toBe(true);
    await expect(ms.closeMilestone(a, { orgId: t.org.id, milestoneId: m1.id, moveOpenIssuesTo: m1.id })).rejects.toBeInstanceOf(NotFoundError);
    const res = await ms.closeMilestone(a, { orgId: t.org.id, milestoneId: m1.id, moveOpenIssuesTo: m2.id });
    expect([...res.movedIssueIds].sort()).toEqual([i1.id, i2.id].sort());
    await expect(issueService.setIssueMilestone(a, { orgId: t.org.id, issueId: i2.id, milestoneId: m1.id })).rejects.toBeInstanceOf(MilestoneStateError);
    list = await ms.listMilestones(a, t.org.id, t.project.id);
    expect(list.map((x) => [x.milestone.name, x.progress.total])).toEqual([["Gamma", 2], ["Beta", 0]]);
    const acts = await activityRepo.listActivity({ orgId: t.org.id, limit: 100, cursor: null } as never);
    console.log(acts.items.filter((e) => e.subjectKind === "milestone").map((e) => e.action));
    const notes = await notificationRepo.listNotifications({ orgId: t.org.id, recipientId: t.userIds.member, unreadOnly: false, limit: 100, cursor: null } as never);
    console.log(notes.items.map((n) => n.kind));
    await ms.reopenMilestone(a, t.org.id, m1.id);
    await expect(ms.reopenMilestone(a, t.org.id, m1.id)).rejects.toBeInstanceOf(MilestoneStateError);
  });
});
EOF
